// Checked against the official sources linked on each page on 12 October 2026.
// Prices are intentionally left to the live regional Meadow pricing table.
const MEADOW = {
  start: "An ongoing Free plan. No credit card required.",
  pricing: "Plans with social-account allowances. Local monthly and yearly prices below.",
  accounts: "Starter: 10 accounts. Creator: 25. Pro: unlimited. Free allowance varies by region.",
  posts: "Unlimited posts on paid plans, subject to platform limits.",
  workflow: "Calendar, drafts, per-account versions, and delivery status for each destination.",
  api: "REST API and remote MCP server for supported clients, with workspace authentication.",
  analytics: "Creator and Pro include available metrics for posts published through Meadow.",
  approvals: "Review saved drafts. No multistage approval chains.",
  networks: "Eleven publishing platforms, including Telegram. Twitch and Kick are chat integrations.",
  inbox: "No unified inbox for social DMs and comments.",
  creation: "Upload your own content and tailor it by account. Work with a supported AI assistant.",
};

const row = (feature, meadow, competitor) => ({ feature, meadow, competitor });
const reason = (title, text) => ({ title, text });
const faq = (q, a) => ({ q, a });
const source = (label, href) => ({ label, href });

function switchingFaqs(name) {
  return [
    faq(`Can I try Meadow before switching from ${name}?`, "Yes. Start with Meadow’s ongoing Free plan without a credit card. Connect an account, prepare a draft, and test the workflow before moving your future posts. Your allowance and local paid prices appear in the pricing table."),
    faq(`Can I move my ${name} schedule into Meadow automatically?`, `There is no automatic ${name} migration. Connect your social accounts to Meadow and recreate the drafts and future posts you want to move. Review captions, media, destination settings, and times. Remove duplicate schedules in your previous tool before they publish. Account IDs and API credentials do not transfer between services.`),
    faq("Can I use Meadow from an AI assistant or my own app?", "Yes. Use the REST API or remote MCP server from a supported client. Authenticate with a private workspace key, or OAuth where supported. Preview content and destinations before approving publication. Publishing is asynchronous; read the final status for each destination after submitting a post."),
    faq("Can I publish to Telegram channels and groups?", "Yes. Connect through the Meadow bot and give it permission to post in your group or channel. Schedule supported text and media alongside other destinations. Meadow tracks delivery status; Telegram post-performance metrics are not available through the Bot API."),
    faq("Which platforms and formats can I use?", "Meadow publishes to Instagram, TikTok, YouTube, Facebook, LinkedIn, X, Threads, Bluesky, Pinterest, Google Business Profile, and Telegram. Supported formats and connections depend on the platform and account permissions. Twitch and Kick support chat messages, not video uploads or live broadcasting."),
  ];
}

function page({ slug, competitor, headline, subtitle, description, comparison, fit, reasons, faqs, sources, disclosure }) {
  return {
    path: `/alternatives/${slug}`,
    kind: "alternative",
    competitor,
    footerLabel: `${competitor} alternative`,
    title: `${competitor} Alternative for Social Publishing | Meadow`,
    description,
    headline,
    subtitle,
    checkedAt: "2026-10-12",
    comparison,
    fit,
    reasons,
    faqs: [...faqs, ...switchingFaqs(competitor)],
    sources,
    ...(disclosure ? { disclosure } : {}),
  };
}

